def backend_command_proof(label,args,environment=None,seconds=120,cwd_override=None):
    started=time.monotonic()
    try:
        result=subprocess.run(args,cwd=cwd_override or repo,env=environment,text=True,capture_output=True,timeout=seconds)
    except subprocess.TimeoutExpired as error:
        record={'label':label,'argv':args,'cwd':str(cwd_override or repo),'failure':'TimeoutExpired','timeoutSeconds':seconds,'stdout':(error.stdout or b'').decode('utf-8',errors='replace') if isinstance(error.stdout,bytes) else (error.stdout or ''),'stderr':(error.stderr or b'').decode('utf-8',errors='replace') if isinstance(error.stderr,bytes) else (error.stderr or '')}
        backend_evidence['validation']['results'].append(record)
        backend_evidence['validation']['failures'].append(record)
        write(str(repo/'docs/c1-stable-backend-tests-evidence.json'),json.dumps(backend_evidence,indent=2)+'\n')
        raise
    record={'label':label,'argv':args,'cwd':str(cwd_override or repo),'exit':result.returncode,'stdout':result.stdout,'stderr':result.stderr,'durationSeconds':round(time.monotonic()-started,3)}
    backend_evidence['validation']['results'].append(record)
    if result.returncode!=0:
        backend_evidence['validation']['failures'].append(record)
    write(str(repo/'docs/c1-stable-backend-tests-evidence.json'),json.dumps(backend_evidence,indent=2)+'\n')
    display(record)
    return result

relativeRuntimeProof.source:
with tempfile.TemporaryDirectory(prefix='c1-two-runtime-') as temporary:
    root=Path(temporary)
    for name in ['home','tmp','work']:
        (root/name).mkdir()
    environment={'PATH':'/usr/bin:/bin','HOME':str(root/'home'),'TMPDIR':str(root/'tmp'),'LANG':'C.UTF-8'}
    commands=[
      ('Existing runner with relative named JS selectors from unrelated cwd',['/usr/bin/node',str(repo/'scripts/run-tests.js'),*backend_active_js]),
      ('Direct Node generated JS from unrelated cwd',['/usr/bin/node','--test',*[str(repo/p) for p in backend_active_js]])
    ]
    results=[]
    for label,args in commands:
        result=backend_command_proof(label,args,environment,90,root/'work')
        if result.returncode!=0:
            backend_stopped=True
            break
        counts={title:len(re.findall(r'^✔ '+re.escape(title)+r' \(',result.stdout,re.MULTILINE)) for titles in backend_active_titles.values() for title in titles}
        assert len(counts)==10 and all(n==1 for n in counts.values())
        assert not list((root/'tmp').iterdir()) and not list((root/'home').iterdir())
        results.append({'label':label,'eachExistingCaseRunsExactlyOnce':counts,'ownedHomeAndTmpEmptyAfterRun':True})
    backend_evidence['relativeRuntimeProof']['results']=results
